{
  "openapi": "3.1.0",
  "info": {
    "title": "Emisell Portal API — local draft/review milestone",
    "version": "1.0.0",
    "description": "Separate admin/developer control-plane principals. No public registration, publishing, runtime activation or merchant management. Developer organization comes exclusively from authenticated membership. Lists return the latest 200. Approved review is NOT a signed or published release. HTTP/loopback development only; not an internet deployment security profile. ADR 0022: authoring/distribusi baru hanya shipping/v1. Payment gateway checkout internal Emisell, bukan aplikasi umum. Record payment historis tetap terbaca; reject/suspend/revoke tersedia. Pengajuan/approval/sign/publish dan kesiapan app-client/Testing payment ditolak. Instalasi/RPC payment fixture tidak diubah."
  },
  "servers": [
    {
      "url": "http://localhost:4317",
      "description": "Admin frontend proxy"
    },
    {
      "url": "http://localhost:4319",
      "description": "Developer frontend proxy"
    }
  ],
  "paths": {
    "/api/v1/portal/login": {"post":{"operationId":"unifiedPortalLogin","description":"Unified dashboard login. Body contains only email/password; identity and surface resolved by backend. Ambiguous matching credentials rejected. Sets HttpOnly host-only emisell_portal_session at /api/v1; HTTPS uses Secure. Exact dashboard origin required. Legacy API permissions remain unchanged.","requestBody":{"required":true,"content":{"application/json":{"schema":{"type":"object","additionalProperties":false,"required":["email","password"],"properties":{"email":{"type":"string"},"password":{"type":"string","format":"password"}}}}}},"responses":{"200":{"description":"Authenticated user with server-selected surface and role"},"401":{"description":"Invalid or ambiguous credentials"},"403":{"description":"Wrong origin"},"429":{"description":"Rate limited"}}}},
    "/api/v1/portal/session": {"get":{"operationId":"unifiedPortalSession","security":[{"UnifiedPortalSession":[]}],"description":"Read unified cookie session. Requires exact dashboard Origin/Referer; returns user with backend-selected surface. Does not accept client role or organization overrides.","responses":{"200":{"description":"Authenticated user"},"401":{"description":"Missing or expired session"},"403":{"description":"Wrong origin"}}}},
    "/api/v1/admin/staff": {
      "get": {
        "operationId": "adminStaffDirectory",
        "security": [{"AdminSession":[]}],
        "description": "Administrator-only read directory of admin portal accounts. Requires admin session and exact Admin Origin/Referer. Returns at most 50 accounts ordered by ID; pass nextAfterId as afterId. Enabled is login eligibility, not online presence. No passwords, sessions, invitations, role changes or developer accounts are exposed.",
        "parameters": [{"name":"afterId","in":"query","schema":{"type":"string","maxLength":200}}],
        "responses": {
          "200": {"description":"Staff page","content":{"application/json":{"schema":{"type":"object","properties":{"accounts":{"type":"array","items":{"type":"object","properties":{"id":{"type":"string"},"email":{"type":"string"},"role":{"type":"string","enum":["administrator","reviewer","operator"]},"enabled":{"type":"boolean"}}}},"nextAfterId":{"type":"string"}}}}}},
          "400":{"description":"Invalid cursor"},
          "401":{"description":"Missing or expired session"},
          "403":{"description":"Wrong origin or not administrator"}
        }
      }
    },
    "/api/v1/admin/developers": {
      "post": {
        "operationId": "adminCreateDeveloper",
        "security": [{"AdminSession":[]},{"UnifiedPortalSession":[]}],
        "description": "Administrator-only account provisioning with exact dashboard Origin. Atomically creates enabled developer login, organization, owner membership and audit entry. Email is normalized and rejected if already used on either surface. Password is hashed, never returned. No invitation email is sent. Not public registration; no existing account is overwritten.",
        "requestBody": {"required":true,"content":{"application/json":{"schema":{"type":"object","additionalProperties":false,"required":["organizationName","email","password"],"properties":{"organizationName":{"type":"string","minLength":1,"maxLength":120},"email":{"type":"string","format":"email","maxLength":254},"password":{"type":"string","format":"password","writeOnly":true,"minLength":12,"maxLength":256,"description":"12–256 UTF-8 bytes, consistent with portal password policy."}}}}}},
        "responses": {
          "201":{"description":"Created organization, containing id, name and memberCount; no credential material"},
          "400":{"description":"Invalid name, email or password"},
          "401":{"description":"Missing or expired session"},
          "403":{"description":"Not administrator or wrong origin"},
          "409":{"description":"Email already in use; no changes made"}
        }
      },
      "get": {
        "operationId": "adminDeveloperOrganizations",
        "security": [{"AdminSession":[]}],
        "description": "Administrator-only read directory. Requires admin session cookie and exact Admin Origin/Referer. Returns at most 50 organizations ordered by ID; use nextAfterId as afterId. No account emails, credentials, or membership writes.",
        "parameters": [{"name":"afterId","in":"query","schema":{"type":"string","maxLength":200}}],
        "responses": {
          "200": {"description":"Organization page","content":{"application/json":{"schema":{"type":"object","properties":{"organizations":{"type":"array","items":{"type":"object","properties":{"id":{"type":"string"},"name":{"type":"string"},"memberCount":{"type":"integer"}}}},"nextAfterId":{"type":"string"}}}}}},
          "401":{"description":"Missing or expired admin session"},
          "403":{"description":"Wrong origin or not administrator"}
        }
      }
    },
    "/api/v1/admin/developers/{id}": {
      "get": {
        "operationId": "adminDeveloperOrganization",
        "security": [{"AdminSession":[]}],
        "description": "Administrator-only organization detail. Requires admin session cookie and exact Admin Origin/Referer. Read-only; no email or credentials returned.",
        "parameters":[{"name":"id","in":"path","required":true,"schema":{"type":"string"}}],
        "responses":{
          "200":{"description":"Organization","content":{"application/json":{"schema":{"type":"object","properties":{"organization":{"type":"object","properties":{"id":{"type":"string"},"name":{"type":"string"},"memberCount":{"type":"integer"}}}}}}}},
          "401":{"description":"Missing or expired admin session"},
          "403":{"description":"Wrong origin or not administrator"},
          "404":{"description":"Organization not found"}
        }
      }
    },
