            "const": false
          },
          "implies": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "requiresAny": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "review": {
            "enum": [
              "standard",
              "restricted"
            ],
            "description": "Policy review Emisell, bukan keputusan/approval Shopify."
          },
          "notes": {
            "type": "string"
          },
          "availableFrom": {
            "type": "string"
          }
        }
      },
      "Catalog": {
        "type": "object",
        "required": [
          "profile",
          "source",
          "checkedAt",
          "grantable",
          "scopes"
        ],
        "properties": {
          "profile": {
            "const": "shopify-authenticated-2026-09-05"
          },
          "source": {
            "const": "https://shopify.dev/docs/api/usage/access-scopes"
          },
          "checkedAt": {
            "const": "2026-09-05"
          },
          "grantable": {
            "const": false
          },
          "scopes": {
            "type": "array",
            "items": {
              "$ref": "#/components/schemas/Scope"
            }
          }
        }
      },
      "Verification": {
        "type": "object",
        "additionalProperties": false,
        "required": [
