            "$ref": "#/components/schemas/Binding"
          },
          "status": {
            "enum": [
              "pending",
              "verified",
              "revoked"
            ]
          },
          "revision": {
            "type": "integer",
            "minimum": 1
          },
          "challengeId": {
            "type": "string"
          },
          "challenge": {
            "type": "string"
          },
          "challengeExpiresAt": {
            "type": "string",
            "format": "date-time"
          },
          "verifiedUntil": {
            "type": [
              "string",
              "null"
            ],
            "format": "date-time"
          },
          "lastAttemptAt": {
            "type": [
              "string",
              "null"
            ],
            "format": "date-time"
          },
          "lastResult": {
            "type": "string"
          },
          "secretVersion": {
            "type": "integer",
            "minimum": 0
          },
          "createdAt": {
            "type": "string",
            "format": "date-time"
          },
