  "info": {"title": "Embedded launch review", "version": "1.0.0", "description": "Opt-in HandlerWithEmbeddedReviews only. Not enabled on default listeners. Review does not grant merchant launch or resource access."},
  "paths": {
    "/api/v1/developer/embedded-launches": {
      "post": {
        "summary": "Ajukan URL Embedded atau Dashboard eksternal",
        "description": "Komposisi opt-in; belum aktif pada server default. Sesi Developer, Origin dan ownership organisasi wajib. App-client harus memiliki proof/secret aktif dan release signed valid. URL harus satu origin dengan endpoint yang diverifikasi. App, digest dan parent origin diturunkan server. Retry metadata identik milik actor yang sama mengembalikan record existing. Tidak memasang aplikasi; launchable selalu false pada tahap ini.",
        "security": [{"DeveloperSession": []}],
        "requestBody": {"required": true,"content": {"application/json": {"schema": {"type": "object", "additionalProperties": false, "required": ["clientId","url","reason"], "properties": {"mode":{"type":"string","enum":["embedded","external"],"description":"Omitted preserves historical embedded metadata. Mode is signed and immutable; external does not issue identity tokens or provide SSO."},"clientId": {"type": "string"},"url": {"type": "string","format": "uri"},"reason": {"type": "string","minLength": 1,"maxLength": 2000}}}}}},
        "responses": {"200": {"description": "Launch tersimpan; bukan grant","content": {"application/json": {"schema": {"$ref": "#/components/schemas/Result"}}}},"400": {"description": "Input atau URL invalid"},"401": {"description": "Sesi invalid"},"403": {"description": "Origin/role ditolak"},"404": {"description": "Client tidak ditemukan dalam organisasi"},"409": {"description": "Client/release belum siap atau metadata conflict"},"503": {"description": "Dependency tidak tersedia"}}
      }
    },
    "/api/v1/developer/app-clients/{id}/launch": {
      "parameters":[{"name":"id","in":"path","required":true,"schema":{"type":"string"}}],
      "get":{"summary":"Baca konfigurasi pembukaan app-client","description":"Opt-in. Ownership organisasi diperiksa sebelum lookup. Launch null berarti belum diajukan, bukan izin membuka aplikasi.","security":[{"DeveloperSession":[]}],"responses":{"200":{"description":"Launch record atau null; launchable false"},"401":{"description":"Sesi invalid"},"404":{"description":"Client tidak tersedia bagi organisasi"}}}
    },
    "/api/v1/admin/app-clients/{id}/launch": {
      "parameters":[{"name":"id","in":"path","required":true,"schema":{"type":"string"}}],
      "get":{"summary":"Baca konfigurasi pembukaan untuk review","description":"Opt-in. Sesi Admin diperlukan. Mode dan URL merupakan metadata signed, bukan grant instalasi.","security":[{"AdminSession":[]}],"responses":{"200":{"description":"Launch record atau null; launchable false"},"401":{"description":"Sesi invalid"},"404":{"description":"Client tidak ditemukan"}}}
    },
