syntax = "proto3";
package emisell.engine.v1;

option go_package = "emisell.app/platform/pkg/sdk/gen/emisell/engine/v1;enginev1";

// Local-isolated API-Kurir only. Uses an independent engine credential, never a
// developer token or full Core key. Each operation must make a fresh check.
service EngineGrantService {
  rpc Check(CheckRequest) returns (CheckResponse);
}
message CheckRequest {
  string merchant_id = 1;
  string provider_code = 2;
  // rates.read or settings.read: never shipment, payment or credential writes.
  string operation = 3;
  string environment = 4;
}
message CheckResponse {
  string merchant_id = 1;
  string provider_code = 2;
  string installation_id = 3;
  string app_id = 4;
  string environment = 5;
  bool allowed = 6;
}

syntax = "proto3";

package emisell.installation.v1;

import "google/protobuf/timestamp.proto";

option go_package = "emisell.app/platform/pkg/sdk/gen/emisell/installation/v1;installationv1";

// Internal first-party Core contract; no installation or active access grant.
// Platform keys require a trusted Core tenant assertion per request. Legacy
// service accounts remain bound to their stored merchant when merchant_id is omitted.
service InstallIntentService {
  rpc Prepare(PrepareRequest) returns (PrepareResponse);
  rpc Get(GetRequest) returns (GetResponse);
  rpc Decide(DecideRequest) returns (DecideResponse);
}

enum IntentState {
  INTENT_STATE_UNSPECIFIED = 0;
  INTENT_STATE_PENDING = 1;
  INTENT_STATE_CONSENTED = 2;
  INTENT_STATE_DENIED = 3;
  INTENT_STATE_EXPIRED = 4;
}

enum ConsentDecision {
  CONSENT_DECISION_UNSPECIFIED = 0;
  CONSENT_DECISION_CONSENT = 1;
  CONSENT_DECISION_DENY = 2;
}

message InstallIntent {
  string id = 1;
  // Deprecated compatibility alias; new callers send merchant_id only.
  string tenant_id = 2 [deprecated = true];
  string core_actor_id = 3;
  string app_id = 4;
  string app_name = 5;
  string developer_id = 6;
  string version = 7;
  string manifest_digest = 8;
  repeated string scopes = 9;
  repeated string capabilities = 10;
  string execution_profile = 11;
  string consent_digest = 12;
  IntentState state = 13;
  google.protobuf.Timestamp created_at = 14;
  google.protobuf.Timestamp expires_at = 15;
  google.protobuf.Timestamp decided_at = 16;
  // Always false in this milestone, including after consent.
  bool execution_allowed = 17;
  // Empty on historical consent-only records. A new prepare + consent is required.
  string installation_policy = 18;
  // Emisell merchant ID, taken from verified Core context. No second store ID.
  string merchant_id = 19;
}

message PrepareRequest {
  // Trusted server-side Core assertion after session and app-management checks.
  string core_actor_id = 1;
  string idempotency_key = 2;
  string app_id = 3;
  string version = 4;
  // Required for platform keys; cannot override a legacy key's tenant binding.
  // Deprecated compatibility alias; new callers send merchant_id only.
  string tenant_id = 5 [deprecated = true];
  // Emisell merchant ID, taken from verified Core context. No second store ID.
  string merchant_id = 6;
}

message PrepareResponse {
  InstallIntent intent = 1;
}

message GetRequest {
  string core_actor_id = 1;
  string intent_id = 2;
  // Deprecated compatibility alias; new callers send merchant_id only.
  string tenant_id = 3 [deprecated = true];
  // Emisell merchant ID, taken from verified Core context. No second store ID.
  string merchant_id = 4;
}

message GetResponse {
  InstallIntent intent = 1;
}

message DecideRequest {
  // Core must recheck actor authority; consent requires explicit user approval.
  string core_actor_id = 1;
  string idempotency_key = 2;
  string intent_id = 3;
  // Echo the exact immutable snapshot displayed by Core; not an auth token.
  string consent_digest = 4;
  ConsentDecision decision = 5;
  // Deprecated compatibility alias; new callers send merchant_id only.
  string tenant_id = 6 [deprecated = true];
  // Emisell merchant ID, taken from verified Core context. No second store ID.
  string merchant_id = 7;
}

message DecideResponse {
  InstallIntent intent = 1;
}

syntax = "proto3";

package emisell.installation.v1;

import "google/protobuf/timestamp.proto";

option go_package = "emisell.app/platform/pkg/sdk/gen/emisell/installation/v1;installationv1";

// Local reviewed executable fixtures only; NOT catalog metadata or Shopify scopes.
// Requires a full platform Core key. Core rechecks staff authority and tenant on
// every call. Detail/mutation ownership includes the preparing service ID AND
// Core actor ID. ListInstallations is a merchant-wide, read-only summary.
service InstallationService {
  rpc ListInstallations(ListInstallationsRequest) returns (ListInstallationsResponse);
  rpc Consume(ConsumeRequest) returns (ConsumeResponse);
  rpc GetInstallation(GetInstallationRequest) returns (GetInstallationResponse);
  rpc Activate(ActivateRequest) returns (ActivateResponse);
  rpc IssueToken(IssueTokenRequest) returns (IssueTokenResponse);
  rpc Uninstall(UninstallRequest) returns (UninstallResponse);
}

// Core must verify the current actor's merchant app-management permission.
// Pagination is a read position, never authorization. Only current intent-managed
// installations are listed; legacy installations and uninstalled history are excluded.
message ListInstallationsRequest {
  string merchant_id = 1;
  string core_actor_id = 2;
  // Default 20, maximum 20. Results ordered by installation_id ascending.
  int32 page_size = 3;
  string after_id = 4;
}

message ListInstallationsResponse {
  string merchant_id = 1;
  repeated InstalledApp installations = 2;
  string next_after_id = 3;
}

// Display metadata only. No consent digest, actor, credentials or action authority.
message InstalledApp {
  string installation_id = 1;
  string app_id = 2;
  string app_name = 3;
  string developer_id = 4;
  string version = 5;
  // pending, active or disabling; not a publication/review status.
  string status = 6;
  string grant_state = 7;
  string execution_profile = 8;
  google.protobuf.Timestamp installed_at = 9;
}

message ConsumeResponse {
  LifecycleResponse result = 1;
}

message GetInstallationRequest {
  InstallationRequest target = 1;
}

message GetInstallationResponse {
  LifecycleResponse result = 1;
}

message ActivateRequest {
  InstallationRequest target = 1;
}

message ActivateResponse {
  LifecycleResponse result = 1;
}

message IssueTokenRequest {
  InstallationRequest target = 1;
}

message IssueTokenResponse {
  LifecycleResponse result = 1;
}

message UninstallRequest {
  InstallationRequest target = 1;
}

message UninstallResponse {
  LifecycleResponse result = 1;
}

message ConsumeRequest {
  // Deprecated compatibility alias; new callers send merchant_id only.
  string tenant_id = 1 [deprecated = true];
  string core_actor_id = 2;
  string idempotency_key = 3;
  string intent_id = 4;
  string consent_digest = 5;
  // Emisell merchant ID, taken from verified Core context. No second store ID.
  string merchant_id = 6;
}

message InstallationRequest {
  // Deprecated compatibility alias; new callers send merchant_id only.
  string tenant_id = 1 [deprecated = true];
  string core_actor_id = 2;
  string installation_id = 3;
  // Required for mutations; omitted for GetInstallation.
  string idempotency_key = 4;
  // Emisell merchant ID, taken from verified Core context. No second store ID.
  string merchant_id = 5;
}

message InstallationAccess {
  string installation_id = 1;
  // Deprecated compatibility alias; new callers send merchant_id only.
  string tenant_id = 2 [deprecated = true];
  string app_id = 3;
  string version = 4;
  // pending, active, disabling or uninstalled. Not publication status.
  string status = 5;
  // pending, active or revoked; only active grants authorize fixture access.
  string grant_state = 6;
  repeated string granted_scopes = 7;
  repeated string requested_scopes = 8;
  repeated string capabilities = 9;
  string intent_id = 10;
  string manifest_digest = 11;
  string execution_profile = 12;
  google.protobuf.Timestamp consumed_at = 13;
  // Emisell merchant ID, taken from verified Core context. No second store ID.
  string merchant_id = 14;
  // Ephemeral GetInstallation decision for the enrolled localhost demo only.
  // Not a resource grant. Missing/false MUST deny embedded identity issuance.
  bool local_embedded_access = 15;
  // Ephemeral current-source decision on GetInstallation only. Absence denies
  // launch; never infer this from the persisted consent snapshot.
  ReviewedUILaunch reviewed_ui_launch = 16;
}

message ReviewedUILaunch {
  string app_id = 1;
  string client_id = 2;
  string release_digest = 3;
  string url = 4;
  string parent_origin = 5;
  string mode = 6;
}

message LifecycleResponse {
  InstallationAccess installation = 1;
  bool replayed = 2;
  // IssueToken only, once; empty on retry. Never log or store in browser.
  string app_token = 3;
  string token_id = 4;
  google.protobuf.Timestamp token_expires_at = 5;
  // On an issuance retry, reflects revocation OR expiry of that original token.
  bool token_invalid = 6;
  // Only the local app installation self-check, NOT resource or internal RPC.
  string token_audience = 7;
}

