  string installation_id = 2;
  bool simulation = 3;
}

syntax = "proto3";

package emisell.resource.product.v1;

import "google/protobuf/timestamp.proto";

option go_package = "emisell.app/platform/pkg/sdk/gen/emisell/resource/product/v1;productv1";

// HANDOFF ONLY: implemented by Emisell Core, not mounted on App Platform :8088.
// Basic product projection only. No variants, inventory, collections or writes.
// Both operations need an active read_products grant (write_products may imply
// it), a trusted server caller, tenant isolation and current grant revision.
service ProductService {
  rpc List(ListRequest) returns (ListResponse);
  rpc Get(GetRequest) returns (GetResponse);
}

// Assertions supplied by App Platform AFTER authentication and grant lookup.
// Core must bind every field to verified caller/delegation and authoritative
// current grant state. Merely receiving this object never authorizes a request.
message AccessContext {
  // Deprecated compatibility alias; new callers send merchant_id only.
  string tenant_id = 1 [deprecated = true];
  string installation_id = 2;
  string app_id = 3;
  string scope_profile = 4;
  int64 grant_revision = 5;
  string request_id = 6;
  // Emisell merchant ID, taken from verified Core context. No second store ID.
  string merchant_id = 7;
}

enum ProductStatus {
  PRODUCT_STATUS_UNSPECIFIED = 0;
  PRODUCT_STATUS_DRAFT = 1;
  PRODUCT_STATUS_ACTIVE = 2;
  PRODUCT_STATUS_ARCHIVED = 3;
}

message ProductFilter {
  // Optional, case-sensitive title prefix, max 100 UTF-8 bytes. No query DSL.
  string title_prefix = 1;
  // UNSPECIFIED means all statuses, not "active" by default.
  ProductStatus status = 2;
}

message ListRequest {
  AccessContext access = 1;
  // Zero means 25; range 1..100 otherwise. Never silently clamp.
  int32 page_size = 2;
  // Opaque, tamper-evident cursor, max 2048 bytes. Bound to the access tuple,
  // grant revision, canonical filter and effective page size. Expiry <=15 min.
  string cursor = 3;
  ProductFilter filter = 4;
}

message GetRequest {
  AccessContext access = 1;
  // Opaque platform ID, 1..100 ASCII [A-Za-z0-9_-]. No Shopify GID assumption.
  string product_id = 2;
}

message Product {
  string id = 1;
  // 1..255 UTF-8 bytes.
  string title = 2;
  // 1..100 ASCII lowercase letters, digits and hyphens.
  string handle = 3;
  ProductStatus status = 4;
  google.protobuf.Timestamp updated_at = 5;
}

message ListResponse {
  // Ascending bytewise product ID, no duplicates; only authorized tenant rows.
  repeated Product products = 1;
  // Empty marks last page. No snapshot consistency guarantee across pages.
  string next_cursor = 2;
}

message GetResponse {
  // Missing or foreign-tenant product returns not_found, never an empty object.
  Product product = 1;
}

syntax = "proto3";

package emisell.shipping.v1;

option go_package = "emisell.app/platform/pkg/sdk/gen/emisell/shipping/v1;shippingv1";

// shipping/v1. This release returns fictional local rates/shipments only.
service ShippingService {
  rpc GetRates(GetRatesRequest) returns (GetRatesResponse);
  rpc Create(CreateRequest) returns (CreateResponse);
  rpc Track(TrackRequest) returns (TrackResponse);
}
message GetRatesRequest {
  // Deprecated compatibility alias; new callers send merchant_id only.
  string tenant_id = 1 [deprecated = true];
  string idempotency_key = 2;
  int32 weight_grams = 3;
  string destination_zone = 4;
  // Emisell merchant ID, taken from verified Core context. No second store ID.
  string merchant_id = 5;
  // Provider-neutral origin zone. Required by the opt-in API-Kurir local reference;
  // legacy simulator requests may omit it. Not a provider location ID.
  string origin_zone = 6;
}
message CreateRequest {
  // Deprecated compatibility alias; new callers send merchant_id only.
  string tenant_id = 1 [deprecated = true];
  string idempotency_key = 2;
  string reference = 3;
  int32 weight_grams = 4;
  string destination_zone = 5;
  // Emisell merchant ID, taken from verified Core context. No second store ID.
  string merchant_id = 6;
}
message TrackRequest {
  // Deprecated compatibility alias; new callers send merchant_id only.
  string tenant_id = 1 [deprecated = true];
  string idempotency_key = 2;
  string resource_id = 3;
  // Emisell merchant ID, taken from verified Core context. No second store ID.
  string merchant_id = 4;
}
message Rate {
  string service = 1;
  int64 amount_minor = 2;
  string currency = 3;
}
message Shipment {
  string id = 1;
  string reference = 2;
  string status = 3;
  int64 amount_minor = 4;
  string currency = 5;
}
message GetRatesResponse {
  repeated Rate rates = 1;
  string installation_id = 2;
  bool simulation = 3;
}
message CreateResponse {
  Shipment shipment = 1;
  string installation_id = 2;
  bool simulation = 3;
}
message TrackResponse {
  Shipment shipment = 1;
  string installation_id = 2;
  bool simulation = 3;
}

syntax = "proto3";

package emisell.testing.v1;

option go_package = "emisell.app/platform/pkg/sdk/gen/emisell/testing/v1;testingv1";

// First-party Core full key only, after Core verifies the current merchant staff.
// Distribution metadata only. This service cannot grant access or install apps.
service TestDistributionService {
  rpc ListAssignments(ListAssignmentsRequest) returns (ListAssignmentsResponse);
}

message ListAssignmentsRequest {
  string merchant_id = 1;
  string core_actor_id = 2;
  // Default and maximum 20, ascending assignment_id; cursor is not authority.
  int32 page_size = 3;
  string after_id = 4;
}

message ListAssignmentsResponse {
  string merchant_id = 1;
  // Only Admin-approved assignments for this merchant, never requested/revoked.
  repeated TestApp apps = 2;
  string next_after_id = 3;
}

message TestApp {
  string assignment_id = 1;
  string app_id = 2;
  string app_name = 3;
  string version = 4;
  string capability = 5;
  TestReadiness readiness = 6;
  // Explicit UI profile; empty preserves legacy capability releases.
  string execution_profile = 7;
}

message TestReadiness {
  bool configuration_ready = 1;
  bool required_scopes_ready = 2;
  // True only for the enabled local managed engine and current signed/approved source.
  bool installable = 3;
  // Stable codes, no provider URLs, credentials, actor or consent data.
  repeated string blockers = 4;
}
